def solve(inp):
    H=len(inp); W=len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    sepR={i for i in range(H) if len(set(inp[i]))==1}
    sepC={j for j in range(W) if len({inp[i][j] for i in range(H)})==1}
    sepcolor=Counter(inp[i][0] for i in sepR|{0} & set()).most_common(1)[0][0] if sepR else None
    sepR={i for i in range(H) if inp[i][:]==inp[i][0] and inp[i][0]!=bg}
    sepC={j for j in range(W) if all(inp[i][j]==inp[0][j] for i in range(H)) and inp[0][j]!=bg}
    def blks(seps,n):
        bs=[];st=0
        for s in sorted(seps):
            bs.append((st,s-1)); st=s+1
        bs.append((st,n-1))
        return bs
    RB=blks(sepR,H); CB=blks(sepC,W)
    # pattern cells = non-bg not in sep lines
    cells=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=bg and r not in sepR and c not in sepC]
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # find source block (the block whose row span overlaps pattern rows and col span overlaps pattern cols)
    src=None
    for bi,(ra,rb) in enumerate(RB):
        for bj,(ca,cb) in enumerate(CB):
            if ra<=r1 and rb>=r0 and ca<=c1 and cb>=c0:
                src=(bi,bj)
    pat=[[inp[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    ph,pw=r1-r0+1,c1-c0+1
    # offset of pattern inside source block
    o_r=o_c=(src[0]*0,src[1]*0)  # placeholder
    dr,dc=r0-RB[src[0]][0], c0-CB[src[1]][0]
    out=[row[:] for row in inp]
    for bi,(ra,rb) in enumerate(RB):
        for bj,(ca,cb) in enumerate(CB):
            if (bi,bj)==src: continue
            for a in range(max(ra,ra+dr)): pass
            for a in range(ra,rb+1):
                for c in range(ca,cb+1):
                    v=pat[a-ra-dr][c-ca-dc] if a-ra-dr>=0 and a-ra-dr<ph and c-ca-dc>=0 and c-ca-dc<pw else None
                    if v is None: continue
                    out[a][c]=v
    return out
